import java.util.*;

enum Direction { UP, DOWN, IDLE }
enum ElevatorState { MOVING, STOPPED, IDLE }

class Request {
    private final int sourceFloor;
    private final int destinationFloor;
    private final Direction direction;
    private final long timestamp;

    public Request(int sourceFloor, int destinationFloor) {
        this.sourceFloor = sourceFloor;
        this.destinationFloor = destinationFloor;
        this.direction = destinationFloor > sourceFloor ? Direction.UP : Direction.DOWN;
        this.timestamp = System.currentTimeMillis();
    }

    public int getSourceFloor()      { return sourceFloor; }
    public int getDestinationFloor() { return destinationFloor; }
    public Direction getDirection()  { return direction; }

    @Override
    public String toString() {
        return "Request(" + sourceFloor + " -> " + destinationFloor + " " + direction + ")";
    }
}

class Elevator {
    private final int id;
    private int currentFloor;
    private Direction direction;
    private ElevatorState state;
    private final TreeSet<Integer> upRequests;
    private final TreeSet<Integer> downRequests;

    public Elevator(int id) {
        this.id = id;
        this.currentFloor = 0;
        this.direction = Direction.IDLE;
        this.state = ElevatorState.IDLE;
        this.upRequests = new TreeSet<>();
        this.downRequests = new TreeSet<>(Collections.reverseOrder());
    }

    public int getId()              { return id; }
    public int getCurrentFloor()    { return currentFloor; }
    public Direction getDirection()  { return direction; }
    public ElevatorState getState() { return state; }

    public int getPendingRequestCount() {
        return upRequests.size() + downRequests.size();
    }

    /**
     * Adds both source and destination floors into the correct request set
     * based on the request direction and the elevator's current state.
     */
    public void addRequest(Request request) {
        int src = request.getSourceFloor();
        int dest = request.getDestinationFloor();

        if (request.getDirection() == Direction.UP) {
            upRequests.add(src);
            upRequests.add(dest);
        } else {
            downRequests.add(src);
            downRequests.add(dest);
        }

        // If elevator is idle, start moving in the request's direction
        if (state == ElevatorState.IDLE) {
            direction = request.getDirection();
            state = ElevatorState.MOVING;
        }

        System.out.println("  Elevator " + id + " accepted " + request);
    }

    /**
     * SCAN (elevator) algorithm:
     *  1. Serve all floors in the current direction.
     *  2. When done, switch direction if the other set is non-empty.
     *  3. If both sets are empty, go IDLE.
     */
    public void processRequests() {
        while (!upRequests.isEmpty() || !downRequests.isEmpty()) {

            if (direction == Direction.UP || direction == Direction.IDLE) {
                processUp();
                if (!downRequests.isEmpty()) {
                    direction = Direction.DOWN;
                    processDown();
                }
            } else {
                processDown();
                if (!upRequests.isEmpty()) {
                    direction = Direction.UP;
                    processUp();
                }
            }
        }
        state = ElevatorState.IDLE;
        direction = Direction.IDLE;
        System.out.println("  Elevator " + id + " is now IDLE at floor " + currentFloor);
    }

    private void processUp() {
        while (!upRequests.isEmpty()) {
            int nextFloor = upRequests.pollFirst();
            moveToFloor(nextFloor);
            openDoor();
        }
    }

    private void processDown() {
        while (!downRequests.isEmpty()) {
            int nextFloor = downRequests.pollFirst();
            moveToFloor(nextFloor);
            openDoor();
        }
    }

    protected void moveToFloor(int floor) {
        System.out.println("  Elevator " + id + " moving " + direction  + " from " + currentFloor + " to " + floor);
        currentFloor = floor;
        state = ElevatorState.MOVING;
    }

    protected void openDoor() {
        state = ElevatorState.STOPPED;
        System.out.println("  Elevator " + id + " stopped at floor " + currentFloor + " — doors open");
    }

    @Override
    public String toString() {
        return "Elevator " + id + "(floor " + currentFloor + ", dir " + direction + ", state " + state + ")";
    }
}

interface ElevatorAssignmentPolicy {
    Elevator selectElevator(List<Elevator> elevators, Request request);
}

/**
 * Picks the nearest elevator that is either:
 *  1. IDLE, or
 *  2. Moving TOWARD the source floor in the SAME direction as the request.
 * Falls back to the elevator with the fewest pending requests.
 */
class NearestElevatorPolicy implements ElevatorAssignmentPolicy {

    @Override
    public Elevator selectElevator(List<Elevator> elevators, Request request) {
        Elevator best = null;
        int bestDist = Integer.MAX_VALUE;

        for (Elevator e : elevators) {
            int dist = Math.abs(e.getCurrentFloor() - request.getSourceFloor());

            // Case 1: elevator is idle — always a candidate
            if (e.getDirection() == Direction.IDLE) {
                if (dist < bestDist) { bestDist = dist; best = e; }
                continue;
            }

            // Case 2: elevator is moving in SAME direction as request
            //         AND hasn't passed the source floor yet
            if (e.getDirection() == request.getDirection()) {
                boolean canPickUp =
                        (request.getDirection() == Direction.UP   && e.getCurrentFloor() <= request.getSourceFloor()) ||
                                (request.getDirection() == Direction.DOWN  && e.getCurrentFloor() >= request.getSourceFloor());
                if (canPickUp && dist < bestDist) { bestDist = dist; best = e; }
            }
        }

        // Fallback: pick the elevator with the least load
        if (best == null) {
            best = Collections.min(elevators, Comparator.comparingInt(Elevator::getPendingRequestCount));
        }
        return best;
    }
}

class ElevatorController {
    private final List<Elevator> elevators;
    private final ElevatorAssignmentPolicy policy;

    public ElevatorController(int numElevators, ElevatorAssignmentPolicy policy) {
        this.policy = policy;
        this.elevators = new ArrayList<>();
        for (int i = 1; i <= numElevators; i++) {
            elevators.add(new Elevator(i));
        }
    }

    public void submitRequest(Request request) {
        System.out.println("\n  New " + request);
        Elevator chosen = policy.selectElevator(elevators, request);
        chosen.addRequest(request);
    }

    public void processAll() {
        System.out.println("\n Processing all elevators");
        for (Elevator e : elevators) {
            e.processRequests();
        }
    }

    public void status() {
        System.out.println("\n Elevator Status");
        for (Elevator e : elevators) {
            System.out.println("  " + e);
        }
    }
}

public class ElevatorSystem {
    public static void main(String[] args) {

        ElevatorAssignmentPolicy policy = new NearestElevatorPolicy();
        ElevatorController controller = new ElevatorController(3, policy);

        // Edge-case 1: same floor request (press button, doors just open)
        controller.submitRequest(new Request(0, 5));   // ground → 5  (UP)
        controller.submitRequest(new Request(3, 0));   // 3 → ground  (DOWN)
        controller.submitRequest(new Request(7, 2));   // 7 → 2       (DOWN)
        controller.submitRequest(new Request(5, 5));   // same floor   (edge)
        controller.submitRequest(new Request(1, 9));   // 1 → 9       (UP, long)

        controller.status();
        controller.processAll();
        controller.status();
    }
}

import java.util.*;

enum Direction {
    UP, DOWN, IDLE
}

class Request {
    int src, dest;
    Direction dir;
    Request(int src, int dest) {
        this.src = src;
        this.dest = dest;
        this.dir = src == dest ? Direction.IDLE : (dest > src ? Direction.UP : Direction.DOWN);
    }
}

class Elevator {
    int id, floor = 0;
    Direction dir = Direction.IDLE;
    TreeSet<Integer> upStops = new TreeSet<>(), downStops = new TreeSet<>(Collections.reverseOrder());

    Elevator(int id) {
        this.id = id;
    }

    void addRequest(Request r) {
        if (r.dir == Direction.IDLE) { // same-floor: just open doors
            floor = r.src;
            System.out.println("Elevator-" + id + " doors open at " + floor);
            return;
        }

        if (r.dir == Direction.UP) {
            upStops.add(r.src);
            upStops.add(r.dest);
        } else {
            downStops.add(r.src);
            downStops.add(r.dest);
        }

        if (dir == Direction.IDLE) dir = r.dir;
    }

    void process() {
        while (!upStops.isEmpty() || !downStops.isEmpty()) {
            if (dir == Direction.UP) {
                serve(upStops);
                if (!downStops.isEmpty())
                    dir = Direction.DOWN;
            }
            if (dir == Direction.DOWN) {
                serve(downStops);
                if (!upStops.isEmpty())
                    dir = Direction.UP;
            }
        }
        dir = Direction.IDLE;
    }

    private void serve(TreeSet<Integer> stops) {
        while (!stops.isEmpty()) {
            floor = stops.pollFirst();
            System.out.println("Elevator-" + id + " stopped at " + floor);
        }
    }

    int pending() {
        return upStops.size() + downStops.size();
    }
}

// Strategy pattern — pluggable assignment policy
interface AssignmentPolicy {
    Elevator select(List<Elevator> elevators, Request req);
}

class NearestPolicy implements AssignmentPolicy {
    public Elevator select(List<Elevator> elevators, Request req) {
        Elevator best = null;
        int bestDist = Integer.MAX_VALUE;

        for (Elevator e : elevators) {
            int d = Math.abs(e.floor - req.src);

            if (e.dir == Direction.IDLE && d < bestDist) {
                best = e;
                bestDist = d;
            }
            else if (e.dir == req.dir) {
                boolean onPath;
                if (req.dir == Direction.UP) {
                    onPath = e.floor <= req.src;
                } else {
                    onPath = e.floor >= req.src;
                }

                if (onPath && d < bestDist) {
                    best = e;
                    bestDist = d;
                }
            }
        }

        if(best!=null) return  best;

        Elevator leastBusy = elevators.get(0);
        for (Elevator e : elevators) {
            if (e.pending() < leastBusy.pending()) {
                leastBusy = e;
            }
        }
        return leastBusy;

       // return best != null ? best : Collections.min(elevators, Comparator.comparingInt(Elevator::pending));
    }
}

class ElevatorController {
    List<Elevator> elevators = new ArrayList<>();
    AssignmentPolicy policy;

    ElevatorController(int n, AssignmentPolicy policy) {
        this.policy = policy;
        for (int i = 1; i <= n; i++)
            elevators.add(new Elevator(i));
    }

    void submit(Request r) {
        Elevator elevator = policy.select(elevators, r);
        elevator.addRequest(r);
    }

    void processAll() {
        elevators.forEach(elevator -> elevator.process());
    }
}

public class ElevatorSystem {
    public static void main(String[] args) {
        ElevatorController ctrl = new ElevatorController(2, new NearestPolicy());
        ctrl.submit(new Request(0, 5));
        ctrl.submit(new Request(3, 0));
        ctrl.submit(new Request(7, 2));
        ctrl.submit(new Request(1, 9));
        ctrl.submit(new Request(2, 6));
        ctrl.processAll();
    }
}

package EmailClassification;

import java.util.*;

/*
 * Entry point (can be used for demo / testing)
 */
public class EmailClassificationSystem {

    public static void main(String[] args) {

        Email email = new Email(
                "1",
                "offers@amazon.com",
                List.of("user@outlook.com"),
                "Big Sale Today",
                "Huge discount on electronics"
        );

        List<Rule> rules = List.of(
                new PromotionKeywordRule(),
                new SpamSenderRule()
        );

        EmailClassifier classifier =
                new HybridEmailClassifier(
                        new RuleBasedClassifier(rules),
                        new MLBasedClassifier()
                );

        EmailClassificationService service =
                new EmailClassificationService(classifier);

        Category category = service.classifyEmail(email);
        System.out.println("Email classified as: " + category);
    }
}

/* ======================= DOMAIN ======================= */

class Email {
    String id;
    String from;
    List<String> to;
    String subject;
    String body;
    Map<String, String> headers = new HashMap<>();

    Email(String id, String from, List<String> to, String subject, String body) {
        this.id = id;
        this.from = from;
        this.to = to;
        this.subject = subject;
        this.body = body;
    }
}

enum Category {
    PRIMARY,
    PROMOTIONS,
    SOCIAL,
    UPDATES,
    SPAM
}

/* =================== STRATEGY =================== */

interface EmailClassifier {
    Category classify(Email email);
}

/* ================= RULE-BASED ================= */

class RuleBasedClassifier implements EmailClassifier {

    private final List<Rule> rules;

    RuleBasedClassifier(List<Rule> rules) {
        this.rules = rules;
    }

    @Override
    public Category classify(Email email) {
        for (Rule rule : rules) {
            if (rule.matches(email)) {
                return rule.getCategory();
            }
        }
        return Category.PRIMARY;
    }
}

/* ================== ML-BASED ================== */

class MLBasedClassifier implements EmailClassifier {

    private final MLModel model = new MLModel();

    @Override
    public Category classify(Email email) {
        return model.predict(email);
    }
}

/* =================== HYBRID =================== */

class HybridEmailClassifier implements EmailClassifier {

    private final EmailClassifier ruleClassifier;
    private final EmailClassifier mlClassifier;

    HybridEmailClassifier(EmailClassifier ruleClassifier,
                          EmailClassifier mlClassifier) {
        this.ruleClassifier = ruleClassifier;
        this.mlClassifier = mlClassifier;
    }

    @Override
    public Category classify(Email email) {
        Category ruleResult = ruleClassifier.classify(email);
        if (ruleResult != Category.PRIMARY) {
            return ruleResult;
        }
        return mlClassifier.classify(email);
    }
}

/* ================== RULES ================== */

interface Rule {
    boolean matches(Email email);
    Category getCategory();
}

class PromotionKeywordRule implements Rule {

    @Override
    public boolean matches(Email email) {
        return email.subject.toLowerCase().contains("sale")
                || email.body.toLowerCase().contains("discount");
    }

    @Override
    public Category getCategory() {
        return Category.PROMOTIONS;
    }
}

class SpamSenderRule implements Rule {

    private static final Set<String> BLACKLIST =
            Set.of("spam@bad.com", "fraud@scam.com");

    @Override
    public boolean matches(Email email) {
        return BLACKLIST.contains(email.from);
    }

    @Override
    public Category getCategory() {
        return Category.SPAM;
    }
}

/* ================= SERVICE ================= */

class EmailClassificationService {

    private final EmailClassifier classifier;

    EmailClassificationService(EmailClassifier classifier) {
        this.classifier = classifier;
    }

    public Category classifyEmail(Email email) {
        return classifier.classify(email);
    }
}

/* ================= ML PLACEHOLDER ================= */

class MLModel {

    Category predict(Email email) {
        // Simulated ML prediction
        if (email.from.contains("linkedin")) {
            return Category.SOCIAL;
        }
        return Category.PRIMARY;
    }
}

import java.util.*;

/*
 * ======================= DEMO =======================
 */
public class EmailClassificationSystem1 {

    public static void main(String[] args) {

        Email1 email = new Email1(
                "1",
                "offers@amazon.com",
                List.of("user@outlook.com"),
                "Big Sale Today",
                "Huge discount on electronics"
        );

        List<Rule1> rules = List.of(
                new SpamSenderRule1(),
                new PromotionKeywordRule1()
        );

        EmailClassifier1 classifier =
                new HybridEmailClassifier1(
                        new RuleBasedClassifier1(rules),
                        new MLBasedClassifier1()
                );

        EmailClassificationService1 service =
                new EmailClassificationService1(classifier);

        ClassificationResult1 result = service.classifyEmail(email);

        System.out.println("Categories : " + result.categories);
        System.out.println("Reason     : " + result.reason);
    }
}

/* ======================= DOMAIN ======================= */

class Email1 {
    final String id;
    final String from;
    final List<String> to;
    final String subject;
    final String body;

    Email1(String id, String from, List<String> to, String subject, String body) {
        this.id = id;
        this.from = from;
        this.to = to;
        this.subject = subject;
        this.body = body;
    }
}

enum Category1 {
    PRIMARY,
    PROMOTIONS,
    SOCIAL,
    UPDATES,
    SPAM
}

/* ======================= RESULT ======================= */

class ClassificationResult1 {
    final Set<Category1> categories;
    final String reason;

    ClassificationResult1(Set<Category1> categories, String reason) {
        this.categories = categories;
        this.reason = reason;
    }
}

/* ======================= STRATEGY ======================= */

interface EmailClassifier1 {
    ClassificationResult1 classify(Email1 email);
}

/* ======================= RULE-BASED ======================= */

class RuleBasedClassifier1 implements EmailClassifier1 {

    private final List<Rule1> rules;

    RuleBasedClassifier1(List<Rule1> rules) {
        this.rules = new ArrayList<>(rules);
        this.rules.sort(Comparator.comparingInt(Rule1::priority));
    }

    @Override
    public ClassificationResult1 classify(Email1 email) {

        Set<Category1> categories = new HashSet<>();
        StringBuilder reason = new StringBuilder();

        for (Rule1 rule : rules) {
            if (rule.matches(email)) {
                categories.add(rule.getCategory());
                reason.append(rule.reason()).append("; ");
            }
        }

        if (categories.isEmpty()) {
            categories.add(Category1.PRIMARY);
            reason.append("No rule matched");
        }

        return new ClassificationResult1(categories, reason.toString());
    }
}

/* ======================= ML-BASED ======================= */

class MLBasedClassifier1 implements EmailClassifier1 {

    private final MLModel1 model = new MLModel1();

    @Override
    public ClassificationResult1 classify(Email1 email) {

        Prediction1 prediction = model.predict(email);

        if (prediction.confidence < 0.7) {
            return new ClassificationResult1(
                    Set.of(Category1.PRIMARY),
                    "ML confidence too low"
            );
        }

        return new ClassificationResult1(
                Set.of(prediction.category),
                "ML predicted with confidence " + prediction.confidence
        );
    }
}

/* ======================= HYBRID ======================= */

class HybridEmailClassifier1 implements EmailClassifier1 {

    private final EmailClassifier1 ruleClassifier;
    private final EmailClassifier1 mlClassifier;

    HybridEmailClassifier1(EmailClassifier1 ruleClassifier,
                           EmailClassifier1 mlClassifier) {
        this.ruleClassifier = ruleClassifier;
        this.mlClassifier = mlClassifier;
    }

    @Override
    public ClassificationResult1 classify(Email1 email) {

        ClassificationResult1 ruleResult = ruleClassifier.classify(email);

        if (!(ruleResult.categories.size() == 1 &&
                ruleResult.categories.contains(Category1.PRIMARY))) {
            return ruleResult;
        }

        return mlClassifier.classify(email);
    }
}

/* ======================= RULES ======================= */

interface Rule1 {
    boolean matches(Email1 email);
    Category1 getCategory();
    int priority();
    String reason();
}

class PromotionKeywordRule1 implements Rule1 {

    @Override
    public boolean matches(Email1 email) {
        return email.subject.toLowerCase().contains("sale")
                || email.body.toLowerCase().contains("discount");
    }

    @Override
    public Category1 getCategory() {
        return Category1.PROMOTIONS;
    }

    @Override
    public int priority() {
        return 2;
    }

    @Override
    public String reason() {
        return "Matched promotion keyword";
    }
}

class SpamSenderRule1 implements Rule1 {

    private static final Set<String> BLACKLIST =
            Set.of("spam@bad.com", "fraud@scam.com");

    @Override
    public boolean matches(Email1 email) {
        return BLACKLIST.contains(email.from);
    }

    @Override
    public Category1 getCategory() {
        return Category1.SPAM;
    }

    @Override
    public int priority() {
        return 1;
    }

    @Override
    public String reason() {
        return "Sender found in blacklist";
    }
}

/* ======================= SERVICE ======================= */

class EmailClassificationService1 {

    private final EmailClassifier1 classifier;

    EmailClassificationService1(EmailClassifier1 classifier) {
        this.classifier = classifier;
    }

    public ClassificationResult1 classifyEmail(Email1 email) {
        return classifier.classify(email);
    }
}

/* ======================= ML PLACEHOLDER ======================= */

class Prediction1 {
    final Category1 category;
    final double confidence;

    Prediction1(Category1 category, double confidence) {
        this.category = category;
        this.confidence = confidence;
    }
}

class MLModel1 {

    Prediction1 predict(Email1 email) {
        if (email.from.contains("linkedin")) {
            return new Prediction1(Category1.SOCIAL, 0.9);
        }
        return new Prediction1(Category1.PRIMARY, 0.6);
    }
}

package FileSystem.CRUDAllOperations;


import java.util.*;

// -------------------- Node --------------------
abstract class Node {
    protected String name;

    Node(String name) {
        this.name = name;
    }

    abstract boolean isFile();
}

// -------------------- File --------------------
class FileNode extends Node {
    private StringBuilder content;

    FileNode(String name) {
        super(name);
        this.content = new StringBuilder();
    }

    @Override
    boolean isFile() {
        return true;
    }

    void addContent(String data) {
        content.append(data);
    }

    void overwriteContent(String data) {
        content.setLength(0);
        content.append(data);
    }

    String read() {
        return content.toString();
    }
}

// -------------------- Directory --------------------
class DirectoryNode extends Node {
    Map<String, Node> children;

    DirectoryNode(String name) {
        super(name);
        this.children = new HashMap<>();
    }

    @Override
    boolean isFile() {
        return false;
    }
}

// -------------------- FileSystem2 --------------------
public class FileSystem2 {

    private final DirectoryNode root;

    public FileSystem2() {
        root = new DirectoryNode("/");
    }

    // -------------------- CREATE --------------------

    public void mkdir(String path) {
        traverseAndCreate(path, false);
    }

    public void addFile(String path, String content) {
        FileNode file = (FileNode) traverseAndCreate(path, true);
        file.addContent(content);
    }

    // -------------------- READ --------------------

    public List<String> ls(String path) {
        Node node = traverse(path);
        List<String> result = new ArrayList<>();

        if (node.isFile()) {
            result.add(node.name);
        } else {
            DirectoryNode dir = (DirectoryNode) node;
            result.addAll(dir.children.keySet());
            Collections.sort(result);
        }
        return result;
    }

    public String readFile(String path) {
        Node node = traverse(path);
        if (!node.isFile()) {
            throw new IllegalArgumentException("Not a file");
        }
        return ((FileNode) node).read();
    }

    // -------------------- UPDATE --------------------

    // overwrite file content
    public void updateFile(String path, String newContent) {
        Node node = traverse(path);
        if (!node.isFile()) {
            throw new IllegalArgumentException("Not a file");
        }
        ((FileNode) node).overwriteContent(newContent);
    }

    // rename file or directory
    public void rename(String path, String newName) {
        ParentAndNode pan = getParent(path);
        DirectoryNode parent = pan.parent;
        Node node = pan.node;

        parent.children.remove(node.name);
        node.name = newName;
        parent.children.put(newName, node);
    }

    // -------------------- DELETE --------------------

    public void delete(String path) {
        ParentAndNode pan = getParent(path);
        pan.parent.children.remove(pan.node.name);
        // GC will take care of recursive cleanup
    }

    // -------------------- Helpers --------------------

    private Node traverse(String path) {
        if (path.equals("/")) return root;

        String[] parts = path.split("/");
        Node curr = root;

        for (int i = 1; i < parts.length; i++) {
            if (!(curr instanceof DirectoryNode)) {
                throw new IllegalArgumentException("Invalid path");
            }
            curr = ((DirectoryNode) curr).children.get(parts[i]);
            if (curr == null) {
                throw new IllegalArgumentException("Path does not exist");
            }
        }
        return curr;
    }

    private Node traverseAndCreate(String path, boolean isFile) {
        String[] parts = path.split("/");
        DirectoryNode curr = root;

        for (int i = 1; i < parts.length; i++) {
            String part = parts[i];

            curr.children.putIfAbsent(
                    part,
                    (i == parts.length - 1 && isFile)
                            ? new FileNode(part)
                            : new DirectoryNode(part)
            );

            Node next = curr.children.get(part);

            // if we are at the last segment, return it
            if (i == parts.length - 1) {
                return next;
            }

            // intermediate nodes MUST be directories
            if (next.isFile()) {
                throw new IllegalArgumentException(
                        "Invalid path: file in the middle of path"
                );
            }

            curr = (DirectoryNode) next;
        }
        return curr;
    }


    // helper to find parent + node
    private ParentAndNode getParent(String path) {
        if (path.equals("/")) {
            throw new IllegalArgumentException("Cannot operate on root");
        }

        int idx = path.lastIndexOf("/");
        String parentPath = (idx == 0) ? "/" : path.substring(0, idx);
        String name = path.substring(idx + 1);

        DirectoryNode parent = (DirectoryNode) traverse(parentPath);
        Node node = parent.children.get(name);

        if (node == null) {
            throw new IllegalArgumentException("Path does not exist");
        }
        return new ParentAndNode(parent, node);
    }
}

// -------------------- Helper DTO --------------------
class ParentAndNode {
    DirectoryNode parent;
    Node node;

    ParentAndNode(DirectoryNode parent, Node node) {
        this.parent = parent;
        this.node = node;
    }
}

/*
✅ CRUD Scope (clear & reasonable)

We will support:

CREATE

    mkdir(path)
    addFile(path, content) (create if not exists)

READ
    ls(path)
    readFile(path)

UPDATE
    updateFile(path, newContent) → overwrite
    rename(path, newName)

DELETE
    delete(path)
    deletes file
    deletes directory recursively
    No over-engineering. No OS semantics.
 */

package FileSystem;


