package FoodDelivery.minimum.dp;

import java.util.*;

/*
    DELIVERY PARTNER ACTOR - FOOD DELIVERY APP

    Covered:
    1. Assign Delivery Partner
    2. Pickup Order
    3. Deliver Order
    4. Delivery Partner Availability
    5. Delivery State Management

    Pattern:
    - Strategy Pattern (Delivery Assignment)
    - State Pattern (Delivery Lifecycle)
*/

public class FoodDeliveryApp {
    public static void main(String[] args) {
        List<DeliveryPartner> partners = new ArrayList<>();
        partners.add(new DeliveryPartner(1, "Rahul"));
        partners.add(new DeliveryPartner(2, "Aman"));

        FoodDelivery.minimum.customer.Order order = new FoodDelivery.minimum.customer.Order(101);

        DeliveryStrategy strategy = new NearestPartnerStrategy();
        DeliveryPartner partner = strategy.assignPartner(partners);

        order.assignPartner(partner);
        System.out.println("\nAssigned Partner : " + partner.getName());

        partner.pickupOrder(order);
        partner.deliverOrder(order);
    }
}

// DELIVERY PARTNER

class DeliveryPartner {
    private int id;
    private String name;
    private boolean available;

    public DeliveryPartner(int id, String name) {
        this.id = id;
        this.name = name;
        this.available = true;
    }

    public boolean isAvailable() {
        return available;
    }

    public String getName() {
        return name;
    }

    public void assignOrder() {
        available = false;
    }

    public void completeOrder() {
        available = true;
    }

    public void pickupOrder(FoodDelivery.minimum.customer.Order order) {
        order.nextState();
        System.out.println("Partner picked up order.");
    }

    public void deliverOrder(FoodDelivery.minimum.customer.Order order) {
        order.nextState();
        completeOrder();
        System.out.println("Order delivered successfully.");
    }
}

// DELIVERY STRATEGY

interface DeliveryStrategy {
    DeliveryPartner assignPartner(List<DeliveryPartner> partners);
}

class NearestPartnerStrategy implements DeliveryStrategy {
    @Override
    public DeliveryPartner assignPartner(List<DeliveryPartner> partners) {
        for (DeliveryPartner partner : partners) {
            if (partner.isAvailable()) {
                partner.assignOrder();
                return partner;
            }
        }
        return null;
    }
}

// ORDER STATUS

enum OrderStatus {
    READY_FOR_PICKUP,
    OUT_FOR_DELIVERY,
    DELIVERED
}

// STATE PATTERN

public interface OrderState {
    void next(FoodDelivery.minimum.customer.Order order);

    FoodDelivery.minimum.customer.OrderStatus getStatus();
}

public class ReadyForPickupState implements OrderState {
    @Override
    public void next(FoodDelivery.minimum.customer.Order order) {
        order.setState(new OutForDeliveryState());
    }

    @Override
    public FoodDelivery.minimum.customer.OrderStatus getStatus() {
        return FoodDelivery.minimum.customer.OrderStatus.READY_FOR_PICKUP;
    }
}

class OutForDeliveryState implements OrderState {
    @Override
    public void next(FoodDelivery.minimum.customer.Order order) {
        order.setState(new DeliveredState());
    }

    @Override
    public FoodDelivery.minimum.customer.OrderStatus getStatus() {
        return FoodDelivery.minimum.customer.OrderStatus.OUT_FOR_DELIVERY;
    }
}

class DeliveredState implements OrderState {
    @Override
    public void next(FoodDelivery.minimum.customer.Order order) {
        System.out.println("Order already delivered.");
    }

    @Override
    public FoodDelivery.minimum.customer.OrderStatus getStatus() {
        return FoodDelivery.minimum.customer.OrderStatus.DELIVERED;
    }
}

// ORDER

class Order {
    private int id;
    private DeliveryPartner partner;
    private OrderState state;

    public Order(int id) {
        this.id = id;
        this.state = new ReadyForPickupState();
    }

    public void assignPartner(DeliveryPartner partner) {
        this.partner = partner;
    }

    public void nextState() {
        System.out.println("\nCURRENT STATE : " + state.getStatus());
        state.next(this);
        System.out.println("NEW STATE     : " + state.getStatus());
    }

    public void setState(OrderState state) {
        this.state = state;
    }
}

package Games.ChessBoard;

import java.util.*;

/**
 * Chess Game - Low Level Design

 Assumptions you should state:
 8×8 chessboard
     2 players (White, Black)
     Standard chess pieces
     Turn-based play
     Valid move checking
     No UI, no AI
 */


/* ======================= POSITION ======================= */

class Position {
    int row;
    int col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/* ======================= PLAYER ======================= */

class Player {
    String name;
    boolean isWhite;

    Player(String name, boolean isWhite) {
        this.name = name;
        this.isWhite = isWhite;
    }
}

/* ======================= MOVE ======================= */

class Move {
    Player player;
    Position from;
    Position to;

    Move(Player player, Position from, Position to) {
        this.player = player;
        this.from = from;
        this.to = to;
    }
}

/* ======================= PIECES ======================= */

abstract class Piece {
    boolean isWhite;

    Piece(boolean isWhite) {
        this.isWhite = isWhite;
    }

    abstract boolean isValidMove(Board board, Position from, Position to);
}

class Rook extends Piece {
    Rook(boolean isWhite) {
        super(isWhite);
    }

    @Override
    boolean isValidMove(Board board, Position from, Position to) {
        return from.row == to.row || from.col == to.col;
    }
}

class Knight extends Piece {
    Knight(boolean isWhite) {
        super(isWhite);
    }

    @Override
    boolean isValidMove(Board board, Position from, Position to) {
        int dr = Math.abs(from.row - to.row);
        int dc = Math.abs(from.col - to.col);
        return (dr == 2 && dc == 1) || (dr == 1 && dc == 2);
    }
}

class Pawn extends Piece {
    Pawn(boolean isWhite) {
        super(isWhite);
    }

    @Override
    boolean isValidMove(Board board, Position from, Position to) {
        int direction = isWhite ? -1 : 1;
        return from.col == to.col && (to.row - from.row) == direction;
    }
}

/* ======================= CELL ======================= */

class Cell {
    Position position;
    Piece piece;

    Cell(Position position) {
        this.position = position;
    }

    boolean isEmpty() {
        return piece == null;
    }
}

/* ======================= BOARD ======================= */

class Board {
    private static final int SIZE = 8;
    private final Cell[][] cells = new Cell[SIZE][SIZE];

    Board() {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                cells[i][j] = new Cell(new Position(i, j));
            }
        }
    }

    void initialize() {
        // Rooks
        cells[0][0].piece = new Rook(false);
        cells[0][7].piece = new Rook(false);
        cells[7][0].piece = new Rook(true);
        cells[7][7].piece = new Rook(true);

        // Knights
        cells[0][1].piece = new Knight(false);
        cells[0][6].piece = new Knight(false);
        cells[7][1].piece = new Knight(true);
        cells[7][6].piece = new Knight(true);

        // Pawns
        for (int i = 0; i < SIZE; i++) {
            cells[1][i].piece = new Pawn(false);
            cells[6][i].piece = new Pawn(true);
        }
    }

    Cell getCell(Position position) {
        if (position.row < 0 || position.row >= SIZE ||
                position.col < 0 || position.col >= SIZE) {
            return null;
        }
        return cells[position.row][position.col];
    }
}

/* ======================= GAME ======================= */

class Game {
    private final Board board;
    private final Player whitePlayer;
    private final Player blackPlayer;
    private Player currentTurn;

    Game(Player whitePlayer, Player blackPlayer) {
        this.board = new Board();
        this.whitePlayer = whitePlayer;
        this.blackPlayer = blackPlayer;
        this.currentTurn = whitePlayer;
        board.initialize();
    }

    public boolean makeMove(Move move) {
        Cell fromCell = board.getCell(move.from);
        Cell toCell = board.getCell(move.to);

        if (fromCell == null || fromCell.isEmpty()) return false;

        Piece piece = fromCell.piece;
        if (piece.isWhite != currentTurn.isWhite) return false;

        if (!piece.isValidMove(board, move.from, move.to)) return false;

        toCell.piece = piece;
        fromCell.piece = null;
        switchTurn();
        return true;
    }

    private void switchTurn() {
        currentTurn = (currentTurn == whitePlayer) ? blackPlayer : whitePlayer;
    }
}

/* ======================= MAIN ======================= */

public class ChessGame {
    public static void main(String[] args) {
        Player white = new Player("White", true);
        Player black = new Player("Black", false);

        Game game = new Game(white, black);

        Move move = new Move(white, new Position(6, 0), new Position(5, 0));
        System.out.println("Move success: " + game.makeMove(move));
    }
}

#include <bits/stdc++.h>
using namespace std;

class Position {
public:
    int row;
    int col;

    Position(int r, int c) : row(r), col(c) {}
};

class Player {
public:
    string name;
    bool isWhite;

    Player(string name, bool isWhite) : name(name), isWhite(isWhite) {}
};

class Piece {
protected:
    bool isWhite;

public:
    Piece(bool isWhite) : isWhite(isWhite) {}

    virtual bool isValidMove(Board &board, Position from, Position to) = 0;

    bool getColor() {
        return isWhite;
    }

    virtual ~Piece() {}
};


class Cell {
public:
    Position position;
    shared_ptr<Piece> piece;

    Cell(int r, int c) : position(r, c), piece(nullptr) {}

    bool isEmpty() {
        return piece == nullptr;
    }
};


class Board {
private:
    static const int SIZE = 8;
    vector<vector<shared_ptr<Cell>>> cells;

public:
    Board() {
        cells.resize(SIZE, vector<shared_ptr<Cell>>(SIZE));

        for(int i=0;i<SIZE;i++){
            for(int j=0;j<SIZE;j++){
                cells[i][j] = make_shared<Cell>(i,j);
            }
        }
    }

    shared_ptr<Cell> getCell(Position pos){
        if(pos.row <0 || pos.row>=SIZE || pos.col<0 || pos.col>=SIZE)
            return nullptr;

        return cells[pos.row][pos.col];
    }

    void placePiece(int r,int c, shared_ptr<Piece> piece){
        cells[r][c]->piece = piece;
    }
};

class Rook : public Piece {
public:
    Rook(bool isWhite) : Piece(isWhite) {}

    bool isValidMove(Board &board, Position from, Position to) override {
        return from.row == to.row || from.col == to.col;
    }
};

class Knight : public Piece {
public:
    Knight(bool isWhite) : Piece(isWhite) {}

    bool isValidMove(Board &board, Position from, Position to) override {

        int dr = abs(from.row - to.row);
        int dc = abs(from.col - to.col);

        return (dr==2 && dc==1) || (dr==1 && dc==2);
    }
};

class Pawn : public Piece {
public:
    Pawn(bool isWhite) : Piece(isWhite) {}

    bool isValidMove(Board &board, Position from, Position to) override {

        int direction = isWhite ? -1 : 1;

        if(from.col == to.col && (to.row-from.row)==direction)
            return true;

        return false;
    }
};

class Move {
public:
    shared_ptr<Player> player;
    Position from;
    Position to;

    Move(shared_ptr<Player> p, Position f, Position t)
        : player(p), from(f), to(t) {}
};

class Game {
private:
    Board board;
    shared_ptr<Player> whitePlayer;
    shared_ptr<Player> blackPlayer;
    shared_ptr<Player> currentTurn;

public:

    Game(shared_ptr<Player> w, shared_ptr<Player> b)
        : whitePlayer(w), blackPlayer(b), currentTurn(w) {

        initializeBoard();
    }

    void initializeBoard(){

        board.placePiece(0,0, make_shared<Rook>(false));
        board.placePiece(0,7, make_shared<Rook>(false));

        board.placePiece(7,0, make_shared<Rook>(true));
        board.placePiece(7,7, make_shared<Rook>(true));

        board.placePiece(0,1, make_shared<Knight>(false));
        board.placePiece(0,6, make_shared<Knight>(false));

        board.placePiece(7,1, make_shared<Knight>(true));
        board.placePiece(7,6, make_shared<Knight>(true));

        for(int i=0;i<8;i++){
            board.placePiece(1,i, make_shared<Pawn>(false));
            board.placePiece(6,i, make_shared<Pawn>(true));
        }
    }

    bool makeMove(Move move){

        auto fromCell = board.getCell(move.from);
        auto toCell = board.getCell(move.to);

        if(!fromCell || fromCell->isEmpty())
            return false;

        auto piece = fromCell->piece;

        if(piece->getColor() != currentTurn->isWhite)
            return false;

        if(!piece->isValidMove(board, move.from, move.to))
            return false;

        toCell->piece = piece;
        fromCell->piece = nullptr;

        switchTurn();

        return true;
    }

    void switchTurn(){
        if(currentTurn == whitePlayer)
            currentTurn = blackPlayer;
        else
            currentTurn = whitePlayer;
    }
};

int main(){
    auto white = make_shared<Player>("White", true);
    auto black = make_shared<Player>("Black", false);

    Game game(white, black);

    int moves;
    cin >> moves;

    while(moves--){

        int fr,fc,tr,tc;
        string player;

        cin >> player >> fr >> fc >> tr >> tc;

        shared_ptr<Player> p = (player=="W") ? white : black;

        Move move(p, Position(fr,fc), Position(tr,tc));

        bool result = game.makeMove(move);

        cout << (result ? "VALID\n" : "INVALID\n");
    }
}

