public class LudoGameSimple {
    public static void main(String[] args) {

        List<Player> players = new ArrayList<>();
        players.add(new Player("Alice", 2));
        players.add(new Player("Bob", 2));

        LudoGame game = new LudoGame(players);
        game.start();
    }
}

