    IN_PLAY,
    FINISHED
};

class Token {

public:
    string id;
    TokenState state;
    int position;

    Token(string id) {
        this->id = id;
        state = TokenState::HOME;
        position = -1;
    }

    bool canMove(int roll) {

        if(state == TokenState::FINISHED)
            return false;

        if(state == TokenState::HOME)
            return roll == 6;

        return position + roll <= 52;
    }

    void move(int roll) {

        if(state == TokenState::HOME && roll == 6) {

            state = TokenState::IN_PLAY;
            position = 0;

            cout << "  " << id << " entered board\n";
        }

        else if(state == TokenState::IN_PLAY) {

            position += roll;

            cout << "  " << id
                 << " -> position "
                 << position << endl;

            if(position >= 52) {

                state = TokenState::FINISHED;

                cout << "  " << id
                     << " finished!\n";
            }
        }
    }
};


class Player {

public:
    string name;
    vector<Token> tokens;

    Player(string name, int tokenCount) {

        this->name = name;

        for(int i = 0; i < tokenCount; i++) {

            tokens.push_back(
                Token(name + "-T" + to_string(i+1))
            );
        }
    }

    bool hasWon() {

        for(auto &t : tokens)
            if(t.state != TokenState::FINISHED)
                return false;

        return true;
    }

    int selectToken(int roll) {

        for(int i = 0; i < tokens.size(); i++)
            if(tokens[i].canMove(roll))
                return i;

        return -1;
    }
};


