package JobSchedulerTask;

import java.util.*;
import java.util.concurrent.*;

// ===================== JobScheduler =====================
public class JobScheduler {

    private final PriorityQueue<ScheduledJob> queue =
            new PriorityQueue<>(Comparator.comparingLong(j -> j.nextRunTime));

    private final ExecutorService executor =
            Executors.newFixedThreadPool(2);

    public synchronized void schedule(Job job, Trigger trigger) {
        queue.offer(new ScheduledJob(job, trigger));
        notify();
    }

    public void start() {
        Thread schedulerThread = new Thread(() -> {
            while (true) {
                try {
                    ScheduledJob scheduledJob;

                    synchronized (this) {
                        while (queue.isEmpty()) {
                            wait();
                        }

                        scheduledJob = queue.peek();
                        long waitTime =
                                scheduledJob.nextRunTime - System.currentTimeMillis();

                        if (waitTime > 0) {
                            wait(waitTime);
                            continue;
                        }

                        queue.poll();
                    }

                    executor.submit(scheduledJob.job::execute);

                    if (scheduledJob.trigger.isRecurring()) {
                        scheduledJob.updateNextRun();
                        synchronized (this) {
                            queue.offer(scheduledJob);
                        }
                    }

                } catch (InterruptedException ignored) {
                }
            }
        });

        schedulerThread.setDaemon(true);
        schedulerThread.start();
    }
}


/*
+-------------------+
|   JobScheduler    |
+-------------------+
| - queue: PriorityQueue<ScheduledJob>
| - executor: ExecutorService
+-------------------+
| + schedule(Job, Trigger)
| + start()
+-------------------+

              |
              | manages
              v

+-------------------+
|   ScheduledJob    |
+-------------------+
| - job: Job
| - trigger: Trigger
| - nextRunTime: long
+-------------------+
| + updateNextRun()
+-------------------+

        |                         |
        | has-a                   | has-a
        v                         v

+-------------------+     +-------------------+
|        Job        |     |     Trigger       |<<interface>>
+-------------------+     +-------------------+
| - task: Runnable |     | + nextRunTime()   |
+-------------------+     | + isRecurring()  |
| + execute()       |     | + update()       |
+-------------------+     +-------------------+
                                  ^
                                  |
                    --------------------------------
                    |                              |
        +---------------------+        +----------------------+
        |   OneTimeTrigger    |        |   IntervalTrigger    |
        +---------------------+        +----------------------+
        | - runAt: long       |        | - nextRun: long      |
        +---------------------+        | - interval: long     |
        | + nextRunTime()     |        +----------------------+
        | + isRecurring()     |        | + nextRunTime()      |
        | + update()          |        | + isRecurring()      |
        +---------------------+        | + update()           |
                                       +----------------------+

 */

package JobSchedulerTask;


import java.time.LocalTime;

public class Main {

    public static void main(String[] args) throws InterruptedException {

        JobScheduler scheduler = new JobScheduler();
        scheduler.start();

        // One-time job (runs after 3 seconds)
        Job oneTimeJob = new Job(() -> {
            System.out.println(
                    "One-time job executed at " + System.currentTimeMillis()
            );
        });

        scheduler.schedule(
                oneTimeJob,
                new OneTimeTrigger(System.currentTimeMillis() + 3000)
        );

        // Recurring job (runs every 2 seconds)
        Job recurringJob = new Job(() -> {
            System.out.println(
                    "Recurring job executed at " + LocalTime.now()
            );
        });

        scheduler.schedule(
                recurringJob,
                new IntervalTrigger(
                        System.currentTimeMillis() + 1000,
                        2000
                )
        );

        // Keep main thread alive for demo
        Thread.sleep(10000);
        System.out.println("Main thread exiting...");
    }
}

