enum VehicleSize {
    SMALL(1),
    MEDIUM(2),
    LARGE(3);

    private final int level;

    VehicleSize(int level) {
        this.level = level;
    }

    boolean canFit(VehicleSize other) {
        return this.level >= other.level;
    }
