package PriorityQueue;

public class MinPriorityQueue {

    private int[] heap;
    private int size;
    private int capacity;

    public MinPriorityQueue(int capacity) {
        this.capacity = capacity;
        this.heap = new int[capacity];
        this.size = 0;
    }

    public void add(int val) {
        if (size == capacity) {
            throw new RuntimeException("Heap is full");
        }

        heap[size] = val;
        siftUp(size);
        size++;
    }

    public int poll() {
        if (isEmpty()) {
            throw new RuntimeException("Heap is empty");
        }

        int min = heap[0];
        heap[0] = heap[size - 1];
        size--;

        siftDown(0);
        return min;
    }

    public int peek() {
        if (isEmpty()) {
            throw new RuntimeException("Heap is empty");
        }
        return heap[0];
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }


    private void siftUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;

            if (heap[parent] <= heap[index]) {
                break;
            }

            swap(parent, index);
            index = parent;
        }
    }

    private void siftDown(int index) {
        while (true) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int smallest = index;

            if (left < size && heap[left] < heap[smallest]) {
                smallest = left;
            }

            if (right < size && heap[right] < heap[smallest]) {
                smallest = right;
            }

            if (smallest == index) {
                break;
            }

            swap(index, smallest);
            index = smallest;
        }
    }

    private void swap(int i, int j) {
        int temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }
}

package RateLimiter.Algoritms;

import RateLimiter.RateLimiter;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

//Fixed Window
class FixedWindow {

    private int count;
    private long windowStart;

    FixedWindow(long now) {
        this.windowStart = now;
        this.count = 0;
    }

    boolean allow(int limit, long windowSizeMillis, long now) {
        if (now - windowStart >= windowSizeMillis) {
            windowStart = now;
            count = 0;
        }

        if (count < limit) {
            count++;
            return true;
        }

        return false;
    }
}

public class FixedWindowRateLimiter implements RateLimiter {

    private final int limit;
    private final long windowSizeMillis;

    private final Map<String, FixedWindow> windows = new ConcurrentHashMap<>();
    private final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public FixedWindowRateLimiter(int limit, long windowSizeMillis) {
        this.limit = limit;
        this.windowSizeMillis = windowSizeMillis;
    }

    @Override
    public boolean allow(String key) {
        ReentrantLock lock = locks.computeIfAbsent(key,k -> new ReentrantLock() );
        lock.lock();
        try {
            long now = System.currentTimeMillis();
            FixedWindow window = windows.computeIfAbsent( key,k -> new FixedWindow(now));

            return window.allow(limit, windowSizeMillis, now);
        } finally {
            lock.unlock();
        }
    }
}

package RateLimiter.Algoritms;

import RateLimiter.RateLimiter;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;


//Leaky Bucket
/*
   Idea:
    Requests enter bucket2
    Bucket leaks at fixed rate
    Burst smoothing
 */


class LeakyBucket {

    private int water;
    private long lastLeakTime;

    LeakyBucket(long now) {
        this.water = 0;
        this.lastLeakTime = now;
    }

    void leak(int leakRatePerSecond, long now) {
        long elapsedSeconds = (now - lastLeakTime) / 1000;

        if (elapsedSeconds <= 0) return;

        int leaked = (int) (elapsedSeconds * leakRatePerSecond);
        water = Math.max(0, water - leaked);
        lastLeakTime = now;
    }

    boolean canAccept(int capacity) {
        return water < capacity;
    }

    void addDrop() {
        water++;
    }
}

public class LeakyBucketRateLimiter implements RateLimiter {

    private final int capacity;
    private final int leakRatePerSecond;

    private final Map<String, LeakyBucket> buckets = new ConcurrentHashMap<>();
    private final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public LeakyBucketRateLimiter(int capacity, int leakRatePerSecond) {
        this.capacity = capacity;
        this.leakRatePerSecond = leakRatePerSecond;
    }

    @Override
    public boolean allow(String key) {
        ReentrantLock lock = locks.computeIfAbsent(key,k -> new ReentrantLock());

        lock.lock();
        try {
            long now = System.currentTimeMillis();
            LeakyBucket bucket = buckets.computeIfAbsent(key,k -> new LeakyBucket(now));
            bucket.leak(leakRatePerSecond, now);

            if (bucket.canAccept(capacity)) {
                bucket.addDrop();
                return true;
            }

            return false;
        } finally {
            lock.unlock();
        }
    }
}

package RateLimiter.Algoritms;

import RateLimiter.RateLimiter;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

class SlidingWindowCounter {

    private static class Window {
        int count;
        long windowStart;

        Window(long windowStart) {
            this.windowStart = windowStart;
            this.count = 0;
        }
    }

    private Window current;
    private Window previous;

    SlidingWindowCounter(long windowStart) {
        this.current = new Window(windowStart);
        this.previous = null;
    }

    boolean allow(int limit, long windowSizeMillis, long now) {
        long currentWindowStart = now - (now % windowSizeMillis);

        // Window moved
        if (current.windowStart != currentWindowStart) {
            previous = current;
            current = new Window(currentWindowStart);
        }

        double prevWeight = 0.0;
        if (previous != null) {
            long elapsed = now - current.windowStart;
            prevWeight =
                    (double) (windowSizeMillis - elapsed) / windowSizeMillis;
        }

        double effectiveCount =
                (previous != null ? previous.count * prevWeight : 0)
                        + current.count;

        if (effectiveCount < limit) {
            current.count++;
            return true;
        }

        return false;
    }
}


public class SlidingWindowCounterRateLimiter implements RateLimiter {

    private final int limit;
    private final long windowSizeMillis;

    private final Map<String, SlidingWindowCounter> counters = new ConcurrentHashMap<>();
    private final Map<String, ReentrantLock> locks =new ConcurrentHashMap<>();

    public SlidingWindowCounterRateLimiter(int limit, long windowSizeMillis) {
        this.limit = limit;
        this.windowSizeMillis = windowSizeMillis;
    }

    @Override
    public boolean allow(String key) {

        ReentrantLock lock = locks.computeIfAbsent(key,k -> new ReentrantLock() );
        lock.lock();
        try {
            long now = System.currentTimeMillis();
            long windowStart = now - (now % windowSizeMillis);

            SlidingWindowCounter counter = counters.computeIfAbsent( key, k -> new SlidingWindowCounter(windowStart));

            return counter.allow(limit, windowSizeMillis, now);

        } finally {
            lock.unlock();
        }
    }
}

package RateLimiter.Algoritms;

import RateLimiter.RateLimiter;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

//Sliding Window

class SlidingWindow {

    private final Deque<Long> timestamps = new ArrayDeque<>();
    boolean allow(int limit, long windowSizeMillis, long now) {

        // Remove expired timestamps
        while (!timestamps.isEmpty()
                && now - timestamps.peekFirst() >= windowSizeMillis) {
            timestamps.pollFirst();
        }

        if (timestamps.size() < limit) {
            timestamps.addLast(now);
            return true;
        }

        return false;
    }
}


public class SlidingWindowRateLimiter implements RateLimiter {

    private final int limit;
    private final long windowSizeMillis;

    private final Map<String, SlidingWindow> windows = new ConcurrentHashMap<>();
    private final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public SlidingWindowRateLimiter(int limit, long windowSizeMillis) {
        this.limit = limit;
        this.windowSizeMillis = windowSizeMillis;
    }

    @Override
    public boolean allow(String key) {
        ReentrantLock lock = locks.computeIfAbsent(key,k -> new ReentrantLock() );

        lock.lock();
        try {
            long now = System.currentTimeMillis();
            SlidingWindow window = windows.computeIfAbsent( key,k -> new SlidingWindow() );
            return window.allow(limit, windowSizeMillis, now);
        } finally {
            lock.unlock();
        }
    }
}

