class FixedWindow {

private:
    int count;
    long long windowStart;

public:
    FixedWindow(long long now) {
        windowStart = now;
        count = 0;
    }

    bool allow(int limit, long long windowSizeMillis, long long now) {

        if (now - windowStart >= windowSizeMillis) {
            windowStart = now;
            count = 0;
        }

        if (count < limit) {
            count++;
            return true;
        }

        return false;
    }
};


