        }
        // Business logic goes here
    }
}

/**
 * RateLimiter Strategy Interface
 */
interface RateLimiter {
    boolean allowRequest(String clientId);
}

/**
 * Fixed Window Rate Limiter Implementation
 */
class FixedWindowRateLimiter implements RateLimiter {

    private final RateLimitRule rule;
    private final ConcurrentHashMap<String, WindowCounter> store = new ConcurrentHashMap<>();

    public FixedWindowRateLimiter(RateLimitRule rule) {
        this.rule = rule;
    }

    @Override
    public boolean allowRequest(String clientId) {
        long currentTime = System.currentTimeMillis() / 1000;
        long windowStart = currentTime - (currentTime % rule.getWindowInSeconds());

        WindowCounter counter = store.computeIfAbsent(
                clientId,
                key -> new WindowCounter(windowStart)
        );

        synchronized (counter) {
            if (counter.getWindowStart() != windowStart) {
                counter.reset(windowStart);
            }

            if (counter.getCount() >= rule.getMaxRequests()) {
                return false;
            }

            counter.increment();
            return true;
        }
    }
}

/**
 * Rate limit rule
 */
class RateLimitRule {

    private final int maxRequests;
    private final long windowInSeconds;

    public RateLimitRule(int maxRequests, long windowInSeconds) {
        this.maxRequests = maxRequests;
        this.windowInSeconds = windowInSeconds;
    }

    public int getMaxRequests() {
        return maxRequests;
    }

    public long getWindowInSeconds() {
        return windowInSeconds;
    }
}

/**
 * Window Counter
 */
class WindowCounter {

    private long windowStart;
    private final AtomicInteger count = new AtomicInteger(0);

    public WindowCounter(long windowStart) {
        this.windowStart = windowStart;
    }

    public long getWindowStart() {
        return windowStart;
    }

    public int getCount() {
        return count.get();
    }

    public void increment() {
        count.incrementAndGet();
    }

    public void reset(long newWindowStart) {
        this.windowStart = newWindowStart;
        count.set(0);
    }
}

package Tier2;

import java.util.*;
        import java.util.concurrent.*;

class LockRecord {
    String lockId;
    String ownerId;
    long expiryTime;

    LockRecord(String lockId, String ownerId, long expiryTime) {
        this.lockId = lockId;
        this.ownerId = ownerId;
        this.expiryTime = expiryTime;
    }
}

class LockService {
    private final Map<String, LockRecord> locks = new ConcurrentHashMap<>();
    private final long leaseMillis;

    LockService(long leaseMillis) {
        this.leaseMillis = leaseMillis;
    }

    public synchronized boolean acquireLock(String lockId, String ownerId) {
        long now = System.currentTimeMillis();
        LockRecord record = locks.get(lockId);

        if (record == null || record.expiryTime < now) {
            locks.put(lockId,
                    new LockRecord(lockId, ownerId, now + leaseMillis));
            return true;
        }
        return false;
    }

    public synchronized boolean renewLock(String lockId, String ownerId) {
        LockRecord record = locks.get(lockId);
        if (record != null && record.ownerId.equals(ownerId)) {
            record.expiryTime = System.currentTimeMillis() + leaseMillis;
            return true;
        }
        return false;
    }

    public synchronized boolean releaseLock(String lockId, String ownerId) {
        LockRecord record = locks.get(lockId);
        if (record != null && record.ownerId.equals(ownerId)) {
            locks.remove(lockId);
            return true;
        }
        return false;
    }
}

class Client {
    private final String clientId;
    private final LockService lockService;

    Client(String clientId, LockService lockService) {
        this.clientId = clientId;
        this.lockService = lockService;
    }

    void doWork(String lockId) {
        if (lockService.acquireLock(lockId, clientId)) {
            try {
                // critical section
            } finally {
                lockService.releaseLock(lockId, clientId);
            }
        }
    }
}

