#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    string name;
    bool isFile;

    Node(string name, bool isFile) : name(name), isFile(isFile) {}
    virtual ~Node() {}
};

class File : public Node {
public:
    string content;

    File(string name) : Node(name, true) {}

    void write(string data) { content = data; }
    void append(string data) { content += data; }
    string read() { return content; }
    int size() { return content.size(); }
};

class Directory : public Node {
public:
    unordered_map<string, shared_ptr<Node>> children;

    Directory(string name) : Node(name, false) {}

    void add(shared_ptr<Node> node) {
        children[node->name] = node;
    }

    void remove(string name) {
        children.erase(name);
    }

    shared_ptr<Node> get(string name) {
        if (children.find(name) != children.end())
            return children[name];
        return nullptr;
    }

    vector<string> list() {
        vector<string> res;
        for (auto &p : children) res.push_back(p.first);
        sort(res.begin(), res.end());
        return res;
    }
};

class FileSystem {
    shared_ptr<Directory> root;

    vector<string> split(string path) {
        vector<string> res;
        string temp;
        for (char c : path) {
            if (c == '/') {
                if (!temp.empty()) res.push_back(temp), temp.clear();
            } else temp.push_back(c);
        }
        if (!temp.empty()) res.push_back(temp);
        return res;
    }

    pair<shared_ptr<Directory>, string> getParent(string path) {
        auto tokens = split(path);
        string name = tokens.back();
        tokens.pop_back();

        auto curr = root;
        for (auto &t : tokens) {
            if (!curr->get(t))
                curr->add(make_shared<Directory>(t));
            curr = static_pointer_cast<Directory>(curr->get(t));
        }
        return {curr, name};
    }

public:
    FileSystem() {
        root = make_shared<Directory>("/");
    }

    void createFile(string path) {
        auto [dir, name] = getParent(path);
        dir->add(make_shared<File>(name));
    }

    void write(string path, string content) {
        auto [dir, name] = getParent(path);
        auto file = static_pointer_cast<File>(dir->get(name));
        file->write(content);
    }

    void append(string path, string content) {
        auto [dir, name] = getParent(path);
        auto file = static_pointer_cast<File>(dir->get(name));
        file->append(content);
    }

    void read(string path) {
        auto [dir, name] = getParent(path);
        auto file = static_pointer_cast<File>(dir->get(name));
        cout << file->read() << endl;
    }

    void deleteNode(string path) {
        auto [dir, name] = getParent(path);
        dir->remove(name);
    }

    void move(string src, string dest) {
        auto [srcDir, srcName] = getParent(src);
        auto node = srcDir->get(srcName);

        auto [destDir, destName] = getParent(dest);
        node->name = destName;

        destDir->add(node);
        srcDir->remove(srcName);
    }

    void ls(string path) {
        auto [dir, name] = getParent(path);
        auto node = dir->get(name);

        if (!node || node->isFile) return;

        auto d = static_pointer_cast<Directory>(node);
        for (auto &x : d->list()) cout << x << " ";
        cout << endl;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    FileSystem fs;
    int q;
    cin >> q;

    while (q--) {
        string cmd;
        cin >> cmd;

        if (cmd == "create") {
            string path;
            cin >> path;
            fs.createFile(path);
        } else if (cmd == "write") {
            string path, content;
            cin >> path >> content;
            fs.write(path, content);
        } else if (cmd == "append") {
            string path, content;
            cin >> path >> content;
            fs.append(path, content);
        } else if (cmd == "read") {
            string path;
            cin >> path;
            fs.read(path);
        } else if (cmd == "delete") {
            string path;
            cin >> path;
            fs.deleteNode(path);
        } else if (cmd == "move") {
            string src, dest;
            cin >> src >> dest;
            fs.move(src, dest);
        } else if (cmd == "ls") {
            string path;
            cin >> path;
            fs.ls(path);
        }
    }
}

