#include <bits/stdc++.h>
using namespace std;

// ---------------- ENUM ----------------
enum class LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR
};

// ---------------- UTILS ----------------
string levelToString(LogLevel level) {
    switch(level) {
        case LogLevel::DEBUG: return "DEBUG";
        case LogLevel::INFO: return "INFO";
        case LogLevel::WARN: return "WARN";
        case LogLevel::ERROR: return "ERROR";
    }
    return "";
}

// ---------------- LOG MESSAGE ----------------
class LogMessage {
public:
    LogLevel level;
    string message;
    time_t timestamp;

    LogMessage(LogLevel level, const string& message)
        : level(level), message(message) {
        timestamp = time(nullptr);
    }
};

// ---------------- FORMATTER ----------------
class Formatter {
public:
    virtual string format(const LogMessage& log) = 0;
    virtual ~Formatter() = default;
};

class SimpleFormatter : public Formatter {
public:
    string format(const LogMessage& log) override {
        return "[" + levelToString(log.level) + "] " + log.message;
    }
};

// ---------------- APPENDER ----------------
class Appender {
protected:
    shared_ptr<Formatter> formatter;

public:
    Appender(shared_ptr<Formatter> fmt) : formatter(fmt) {}
    virtual void append(const LogMessage& log) = 0;
    virtual ~Appender() = default;
};

class ConsoleAppender : public Appender {
public:
    ConsoleAppender(shared_ptr<Formatter> fmt) : Appender(fmt) {}

    void append(const LogMessage& log) override {
        cout << formatter->format(log) << endl;
    }
};

class FileAppender : public Appender {
private:
    string filename;

public:
    FileAppender(const string& file, shared_ptr<Formatter> fmt)
        : Appender(fmt), filename(file) {}

    void append(const LogMessage& log) override {
        ofstream fout(filename, ios::app);
        fout << formatter->format(log) << endl;
        fout.close();
    }
};

// ---------------- LOGGER ----------------
class Logger {
private:
    vector<shared_ptr<Appender>> appenders;
    LogLevel minLevel;

public:
    Logger(LogLevel level) : minLevel(level) {}

    void addAppender(shared_ptr<Appender> appender) {
        appenders.push_back(appender);
    }

    void log(LogLevel level, const string& message) {
        if ((int)level < (int)minLevel) return;

        LogMessage logMsg(level, message);

        for (auto& appender : appenders) {
            appender->append(logMsg);
        }
    }
};

// ---------------- FACTORY ----------------
class LoggerFactory {
public:
    static shared_ptr<Logger> createLogger(LogLevel level, const string& file) {
        auto formatter = make_shared<SimpleFormatter>();

        auto logger = make_shared<Logger>(level);

        logger->addAppender(make_shared<ConsoleAppender>(formatter));
        logger->addAppender(make_shared<FileAppender>(file, formatter));

        return logger;
    }
};

// ---------------- PARSER ----------------
LogLevel parseLevel(const string& level) {
    if (level == "DEBUG") return LogLevel::DEBUG;
    if (level == "INFO") return LogLevel::INFO;
    if (level == "WARN") return LogLevel::WARN;
    return LogLevel::ERROR;
}

// ---------------- MAIN ----------------
int main() {
    int n;
    cin >> n;

    string minLevelStr, filename;
    cin >> minLevelStr >> filename;

    auto logger = LoggerFactory::createLogger(parseLevel(minLevelStr), filename);

    cin.ignore();

    while (n--) {
        string levelStr, message;
        cin >> levelStr;
        getline(cin, message);

        // remove leading space
        if (!message.empty() && message[0] == ' ') {
            message = message.substr(1);
        }

        logger->log(parseLevel(levelStr), message);
    }

    return 0;
}

import java.util.*;
import java.util.concurrent.locks.*;

/************** Message *****************/
class Message {
    int id;
    String payload;

    public Message(int id, String payload) {
        this.id = id;
        this.payload = payload;
    }
}

/************** Topic *****************/
class Topic {
    private String name;
    private List<Message> messages;
    private Lock lock;

    public Topic(String name) {
        this.name = name;
        this.messages = new ArrayList<>();
        this.lock = new ReentrantLock();
    }

    public void publish(Message msg) {
        lock.lock();
        try {
            messages.add(msg);
        } finally {
            lock.unlock();
        }
    }

    public Message getMessage(int offset) {
        lock.lock();
        try {
            if (offset < messages.size()) {
                return messages.get(offset);
            }
            return null;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return messages.size();
        } finally {
            lock.unlock();
        }
    }

    public String getName() {
        return name;
    }
}

/************** Consumer *****************/
class Consumer {
    private String name;
    private Map<String, Integer> offsets;

    public Consumer(String name) {
        this.name = name;
        this.offsets = new HashMap<>();
    }

    public void consume(Topic topic) {
        String tname = topic.getName();

        offsets.putIfAbsent(tname, 0);

        int offset = offsets.get(tname);
        Message msg = topic.getMessage(offset);

        if (msg != null) {
            System.out.println(name + " consumed from " + tname + ": " + msg.payload);
            offsets.put(tname, offset + 1);
        } else {
            System.out.println(name + " no new messages in " + tname);
        }
    }
}

/************** Producer *****************/
class Producer {
    private String name;

    public Producer(String name) {
        this.name = name;
    }

    public void publish(Topic topic, int id, String payload) {
        Message msg = new Message(id, payload);
        topic.publish(msg);

        System.out.println(name + " published to " + topic.getName() + ": " + payload);
    }
}

/************** MessageQueue *****************/
class MessageQueue {
    private Map<String, Topic> topics;

    public MessageQueue() {
        topics = new HashMap<>();
    }

    public Topic createTopic(String name) {
        topics.putIfAbsent(name, new Topic(name));
        return topics.get(name);
    }

    public Topic getTopic(String name) {
        return topics.get(name);
    }
}

/************** MAIN *****************/

public class Main {
    public static void main(String[] args) {

        MessageQueue mq = new MessageQueue();

        // Create Topic
        Topic orders = mq.createTopic("orders");

        // Create Producers
        Producer p1 = new Producer("p1");

        // Create Consumers
        Consumer c1 = new Consumer("c1");
        Consumer c2 = new Consumer("c2");

        // Publish messages
        p1.publish(orders, 1, "orderA");
        p1.publish(orders, 2, "orderB");

        System.out.println();

        // Consumer 1 consumes
        c1.consume(orders);
        c1.consume(orders);
        c1.consume(orders); // no new message

        System.out.println();

        // Consumer 2 consumes (independent offset)
        c2.consume(orders);
        c2.consume(orders);
    }
}

