    auto car1 = make_unique<Vehicle>("CAR123", VehicleType::CAR);
    auto car2 = make_unique<Vehicle>("CAR456", VehicleType::CAR);

    cout << lot.park(move(car1)) << endl;  // 1
    cout << lot.park(move(car2)) << endl;  // 1

    return 0;
}


