#include <bits/stdc++.h>
using namespace std;

/************** Message *****************/
class Message {
public:
    int id;
    string payload;

    Message(int id, string payload) : id(id), payload(payload) {}
};

/************** Topic *****************/
class Topic {
private:
    string name;
    vector<shared_ptr<Message>> messages;
    mutex mtx;

public:
    Topic(string name) : name(name) {}

    void publish(shared_ptr<Message> msg) {
        lock_guard<mutex> lock(mtx);
        messages.push_back(msg);
    }

    shared_ptr<Message> getMessage(int offset) {
        lock_guard<mutex> lock(mtx);
        if (offset < messages.size()) return messages[offset];
        return nullptr;
    }

    int size() {
        lock_guard<mutex> lock(mtx);
        return messages.size();
    }

    string getName() { return name; }
};

/************** Consumer *****************/
class Consumer {
private:
    string name;
    unordered_map<string, int> offsets; // topic -> offset

public:
    Consumer(string name) : name(name) {}

    void consume(shared_ptr<Topic> topic) {
        string tname = topic->getName();

        if (offsets.find(tname) == offsets.end())
            offsets[tname] = 0;

        int offset = offsets[tname];
        auto msg = topic->getMessage(offset);

        if (msg) {
            cout << name << " consumed from " << tname
                 << ": " << msg->payload << "\n";
            offsets[tname]++;
        } else {
            cout << name << " no new messages in " << tname << "\n";
        }
    }
};

/************** Producer *****************/
class Producer {
private:
    string name;

public:
    Producer(string name) : name(name) {}

    void publish(shared_ptr<Topic> topic, int id, string payload) {
        auto msg = make_shared<Message>(id, payload);
        topic->publish(msg);

        cout << name << " published to " << topic->getName()
             << ": " << payload << "\n";
    }
};

/************** MessageQueue System *****************/
class MessageQueue {
private:
    unordered_map<string, shared_ptr<Topic>> topics;

public:
    shared_ptr<Topic> createTopic(string name) {
        if (topics.find(name) == topics.end()) {
            topics[name] = make_shared<Topic>(name);
        }
        return topics[name];
    }

    shared_ptr<Topic> getTopic(string name) {
        if (topics.find(name) != topics.end())
            return topics[name];
        return nullptr;
    }
};

/************** MAIN *****************/
int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    MessageQueue mq;
    unordered_map<string, shared_ptr<Producer>> producers;
    unordered_map<string, shared_ptr<Consumer>> consumers;

    int q;
    cin >> q;

    while (q--) {
        string cmd;
        cin >> cmd;

        if (cmd == "CREATE_TOPIC") {
            string topic;
            cin >> topic;
            mq.createTopic(topic);
            cout << "Topic created: " << topic << "\n";
        }

        else if (cmd == "CREATE_PRODUCER") {
            string name;
            cin >> name;
            producers[name] = make_shared<Producer>(name);
            cout << "Producer created: " << name << "\n";
        }

        else if (cmd == "CREATE_CONSUMER") {
            string name;
            cin >> name;
            consumers[name] = make_shared<Consumer>(name);
            cout << "Consumer created: " << name << "\n";
        }

        else if (cmd == "PUBLISH") {
            string pname, topic, payload;
            int id;
            cin >> pname >> topic >> id >> payload;

            auto t = mq.getTopic(topic);
            if (t && producers.count(pname)) {
                producers[pname]->publish(t, id, payload);
            }
        }

        else if (cmd == "CONSUME") {
            string cname, topic;
            cin >> cname >> topic;

            auto t = mq.getTopic(topic);
            if (t && consumers.count(cname)) {
                consumers[cname]->consume(t);
            }
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

enum class DriverStatus { AVAILABLE, BUSY };

class Location {
public:
    double x, y;

    Location(double x=0, double y=0) : x(x), y(y) {}

    double distance(const Location& other) const {
        return hypot(x-other.x, y-other.y);
    }
};

class Driver {

    string id;
    Location loc;
    DriverStatus status;

public:

    Driver(string id, Location l) : id(id), loc(l), status(DriverStatus::AVAILABLE) {}

    string getId() const { return id; }

    Location getLocation() const { return loc; }

    bool isAvailable() const {
        return status == DriverStatus::AVAILABLE;
    }

    void assignRide() {
        status = DriverStatus::BUSY;
    }

    void completeRide() {
        status = DriverStatus::AVAILABLE;
    }
};

class Rider {

    string id;

public:
    Rider(string id) : id(id) {}
    string getId() const { return id; }
};

class Ride {

    string rideId;
    shared_ptr<Rider> rider;
    shared_ptr<Driver> driver;

public:

    Ride(string id, shared_ptr<Rider> r) : rideId(id), rider(r) {}

    void assignDriver(shared_ptr<Driver> d) {
        driver = d;
        driver->assignRide();

        cout << "Ride " << rideId
             << " assigned to Driver "
             << driver->getId() << endl;
    }

    void completeRide() {

        if(driver) {
            driver->completeRide();
            cout << "Ride " << rideId << " completed\n";
        }
    }
};

class MatchingStrategy {

public:

    virtual shared_ptr<Driver> matchDriver(
        Location src,
        vector<shared_ptr<Driver>>& drivers) = 0;

    virtual ~MatchingStrategy() = default;
};

class NearestDriverStrategy : public MatchingStrategy {

public:

    shared_ptr<Driver> matchDriver(
        Location src,
        vector<shared_ptr<Driver>>& drivers) override {

        shared_ptr<Driver> best = nullptr;
        double minDist = INT_MAX;

        for(auto &d : drivers) {

            if(!d->isAvailable()) continue;

            double dist = d->getLocation().distance(src);

            if(dist < minDist) {
                minDist = dist;
                best = d;
            }
        }

        return best;
    }
};

class RideManager {

    vector<shared_ptr<Driver>> drivers;
    unordered_map<string, shared_ptr<Ride>> rides;

    unique_ptr<MatchingStrategy> strategy;

public:

    RideManager() {
        strategy = make_unique<NearestDriverStrategy>();
    }

    void initDriver(string id, double x, double y) {

        drivers.push_back(
            make_shared<Driver>(id, Location(x,y))
        );

        cout << "Driver " << id << " added\n";
    }

    void requestRide(string rideId, string riderId,
                     double sx, double sy) {

        auto rider = make_shared<Rider>(riderId);

        auto ride = make_shared<Ride>(rideId, rider);

        auto driver =
            strategy->matchDriver(Location(sx,sy), drivers);

        if(!driver) {
            cout << "No drivers available\n";
            return;
        }

        ride->assignDriver(driver);

        rides[rideId] = ride;
    }

    void completeRide(string rideId) {

        if(rides.count(rideId)) {
            rides[rideId]->completeRide();
        }
    }
};

int main() {

    RideManager manager;

    string cmd;

    while(cin >> cmd) {

        if(cmd == "INIT_DRIVER") {

            string id;
            double x,y;

            cin >> id >> x >> y;

            manager.initDriver(id,x,y);
        }

        else if(cmd == "REQUEST_RIDE") {

            string rideId,riderId;
            double x,y;

            cin >> rideId >> riderId >> x >> y;

            manager.requestRide(rideId,riderId,x,y);
        }

        else if(cmd == "COMPLETE_RIDE") {

            string rideId;
            cin >> rideId;

            manager.completeRide(rideId);
        }

        else if(cmd == "EXIT")
            break;
    }
}

