    private Inventory inventory;
    private int balance = 0;
    private int selectedSlot = -1;

    VendingMachine() {
        inventory = new Inventory();
        state = new IdleState();
    }

    void setState(State state) {
        this.state = state;
    }

    Inventory getInventory() {
        return inventory;
    }

