    public void selectProduct(VendingMachine vm, int slot) {
        System.out.println("Already selected");
    }

    public void dispense(VendingMachine vm) {
        int slot = vm.getSlot();
        Inventory inv = vm.getInventory();
        Item item = inv.getItem(slot);
        inv.reduce(slot);
